c022.try_sql:
-- The string literal is converted with the session's NLS_DATE_FORMAT (here YYYY-MM-DD ...), so this is an error
SELECT COUNT(*) FROM orders o WHERE o.order_date > TO_DATE('31/03/2024', 'DD/MM/YYYY');
SELECT COUNT(*) FROM orders o WHERE o.order_date > '31/03/2024';

c210.try_sql:
-- From the inside out: SUBSTR, then UPPER, then LPAD
SELECT LPAD(UPPER(SUBSTR(e.last_name, 1, 3)), 5, '*') AS nested
FROM   employees e
WHERE  e.employee_id = 100;
-- Group functions: at most two levels (MAX of AVG per department)
SELECT MAX(AVG(e.salary)) AS max_avg FROM employees e GROUP BY e.department_id;

c212.try_sql:
-- The operator decides the direction: + gives a number, || gives text
SELECT '10' + 5 AS plus, '10' || 5 AS concat FROM dual;
-- Every email is converted to NUMBER: error
SELECT COUNT(*) FROM employees e WHERE e.email = 100;

c214.try_sql:
-- DECODE without a default gives NULL outside department 10
SELECT e.employee_id, DECODE(e.department_id, 10, 'Admin') AS dept
FROM   employees e
WHERE  e.employee_id IN (100, 101);
-- CASE with NUMBER and text in its results: error
SELECT CASE WHEN 1 = 1 THEN 1 ELSE 'x' END AS r FROM dual;

c215.try_sql:
-- Without fx: other separators and missing leading zeros are fine
SELECT TO_DATE('2024/3/5', 'YYYY-MM-DD') AS ok FROM dual;
-- 30 February does not exist: error
SELECT TO_DATE('2024-02-30', 'YYYY-MM-DD') AS bad FROM dual;

c1250.try_sql:
-- COALESCE stops at 1, while NVL also evaluates 1/0
SELECT COALESCE(1, 1/0) AS c FROM dual;
SELECT NVL(1, 1/0) AS n FROM dual;

c1251.try_sql:
-- Result type = NUMBER (the first result), so 'n/a' raises an error
SELECT e.employee_id, DECODE(e.department_id, 10, 100, 'n/a') AS r
FROM   employees e;

c1252.try_sql:
-- With +, text becomes NUMBER: the first works, the second does not
SELECT DATE '2024-03-01' + '1' AS d FROM dual;
SELECT '2024-03-01' + 1 AS d FROM dual;

c1253.try_sql:
-- LIKE on NUMBER and DATE: implicit conversion to text (the date with NLS_DATE_FORMAT)
SELECT e.last_name, e.salary FROM employees e WHERE e.salary LIKE '6%';
SELECT e.last_name, e.hire_date FROM employees e WHERE e.hire_date LIKE '%-01-%';

c1259.try_sql:
-- A format longer than the string works (midnight), a shorter one raises an error
SELECT TO_DATE('2024-03-05', 'YYYY-MM-DD HH24:MI') AS ok FROM dual;
SELECT TO_DATE('2024-03-05 10:30', 'YYYY-MM-DD') AS bad FROM dual;
